class Solution:
    def countPartitions(self, field: List[str]) -> int:
        n = len(field[0]); cnt = 0
        for k in range(2):
            a, b = field[k], field[1 - k]
            for i in range(1, n - 1):
                if a[i - 1] == a[i] == a[i + 1] == "o" and b[i - 1] == "x" and b[i] == "o" and b[i + 1] == "x": cnt += 1
        return cnt

